out <- 'tmp/margin-method-notes-i18n';dir.create(out,recursive=TRUE,showWarnings=FALSE)
base <- list(effect_size_equivalence_margin='.25',effect_size_equivalence_sd='2',effect_size_equivalence_p1='.25',effect_size_equivalence_p2='.5')
cases <- expand.grid(outcome=c('mean','proportion'),objective=c('equivalence','noninferiority'),stringsAsFactors=FALSE)
results <- lapply(seq_len(nrow(cases)),function(i)effect_size_equivalence_calculate(modifyList(base,list(effect_size_equivalence_outcome=cases$outcome[i],effect_size_equivalence_objective=cases$objective[i],effect_size_equivalence_difference='-.125'))))
extra <- expand.grid(objective=c('equivalence','noninferiority'),difference=c(-.25,-.5),stringsAsFactors=FALSE)
results <- c(results,lapply(seq_len(nrow(extra)),function(i)effect_size_equivalence_calculate(modifyList(base,list(effect_size_equivalence_outcome='mean',effect_size_equivalence_objective=extra$objective[i],effect_size_equivalence_difference=as.character(extra$difference[i]))))),list(effect_size_diagnostic_calculate(list(effect_size_diagnostic_auc='.8',effect_size_diagnostic_null_auc='.5'))))
designs <- c(paste(cases$outcome,cases$objective),paste(extra$objective,extra$difference),'auc')
objectives <- c(cases$objective,extra$objective)
formula_keys <- paste0('sample_size.result.',c(ifelse(objectives=='equivalence','note_equivalence_inside','note_noninferiority_above'),'diagnostic_auc'))
for(i in seq_along(results))stopifnot(is.null(results[[i]]$error),identical(results[[i]]$method_note,statedu_t(formula_keys[i],'en')))
distances <- c(.125,0,.125,0,0,0,-.25,-.25)
for(i in 1:8)stopifnot(isTRUE(all.equal(results[[i]]$distance_to_margin,distances[i])),identical(results[[i]]$inside_margin,if(distances[i]>0)'Yes' else 'No'))
for(i in c(1,3,5:8))stopifnot(isTRUE(all.equal(results[[i]]$standardized_distance,distances[i]/2)))
for(i in c(2,4))stopifnot(isTRUE(all.equal(results[[i]]$standardized_effect,-.25/sqrt(.375*.625))))
stopifnot(isTRUE(all.equal(results[[9]]$auc_difference,.3)),isTRUE(all.equal(results[[9]]$auc_cohen_d,sqrt(2)*qnorm(.8))))
for(lang in c('en','ko','ja','zh','es','fr','de','vi')) {
 stopifnot(grepl('margin - abs(observed effect)',statedu_t(formula_keys[1],lang),fixed=TRUE),grepl('margin + observed effect',statedu_t(formula_keys[3],lang),fixed=TRUE),grepl('-margin',statedu_t(formula_keys[3],lang),fixed=TRUE))
}
cat('PASS nine actual margin/AUC cases including exact and outside boundaries; eight-language expression checks\n')
